<?php
require_once __DIR__.'/../includes/bootstrap.php';
$user=require_login('provider');
$stmt=db()->prepare('SELECT id,business_name FROM providers WHERE user_id=? LIMIT 1');$stmt->bind_param('i',$user['id']);$stmt->execute();$provider=$stmt->get_result()->fetch_assoc();if(!$provider)exit('Provider profile not found.');
$stmt=db()->prepare("SELECT pb.*,tr.request_number,tr.destination,tr.start_date,tr.end_date,tr.status AS request_status FROM provider_bids pb JOIN trip_requests tr ON tr.id=pb.trip_request_id WHERE pb.provider_id=? ORDER BY pb.created_at DESC");$stmt->bind_param('i',$provider['id']);$stmt->execute();$offers=$stmt->get_result();
$page_title='My Offers';require __DIR__.'/../includes/header.php';
?><div class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">My Offers</h1><p class="text-secondary mb-0">Manage submitted packages and review their current status.</p></div><a class="btn btn-outline-dark" href="/provider/dashboard.php">Marketplace</a></div><div class="card"><div class="card-body"><?php if(!$offers->num_rows):?><p class="text-secondary mb-0">You have not submitted any offers yet.</p><?php else:?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Offer</th><th>Trip</th><th>Amount</th><th>Status</th><th>Request</th><th></th></tr></thead><tbody><?php while($o=$offers->fetch_assoc()):?><tr><td><strong><?=e($o['bid_number'])?></strong><br><small class="text-secondary"><?=e($o['created_at'])?></small></td><td><?=e($o['destination'])?><br><small class="text-secondary"><?=e($o['start_date'])?> → <?=e($o['end_date'])?></small></td><td><?=e($o['currency'])?> <?=number_format((float)$o['total_amount'],2)?></td><td><span class="badge text-bg-light"><?=e($o['status'])?></span></td><td><?=e($o['request_status'])?></td><td><a class="btn btn-sm btn-outline-dark" href="/provider/bid-items.php?bid_id=<?=$o['id']?>">Package</a></td></tr><?php endwhile;?></tbody></table></div><?php endif;?></div></div></div><?php require __DIR__.'/../includes/footer.php'; ?>